// Geometry resources are reference-counted across systems. Aliases share the
// same coordinate/station arrays, but retain their own operator/service keys.
globalThis.RailDataStore=class RailDataStore {
 constructor(files,{fetcher=globalThis.fetch,onChange=()=>{}}={}){this.files=files;this.fetcher=fetcher.bind(globalThis);this.onChange=onChange;this.records=new Map();this.resources=new Map();this.wanted=new Set()}
 snapshot(){return {rails:[...this.records.values()].flatMap(r=>r.data||[]),states:Object.fromEntries([...this.records].map(([key,r])=>[key,{status:r.status,error:r.error||null}]))}}
 emit(){this.onChange(this.snapshot())}
 release(record){record.data=null;for(const url of record.urls||[]){const resource=this.resources.get(url);if(!resource)continue;resource.users.delete(record);if(!resource.users.size){resource.controller.abort();this.resources.delete(url)}}}
 setWanted(keys){this.wanted=new Set(keys);for(const [key,record]of this.records){if(!this.wanted.has(key)){this.release(record);this.records.delete(key)}}for(const key of this.wanted){if(this.files[key]&&!this.records.has(key))this.load(key)}this.emit()}
 acquire(url,record){let resource=this.resources.get(url);if(!resource){resource={users:new Set(),controller:new AbortController()};this.resources.set(url,resource);resource.promise=(async()=>{const response=await this.fetcher(url,{signal:resource.controller.signal});if(!response.ok)throw Error('HTTP '+response.status);const rows=await response.json();if(!Array.isArray(rows))throw Error('Invalid railway data');return rows})()}resource.users.add(record);record.urls.push(url);return resource.promise}
 load(key){const record={status:'loading',data:null,urls:[]};this.records.set(key,record);this.emit();record.promise=(async()=>{try{const file=this.files[key],specs=[{url:file.url},...(file.shared||[])],rows=await Promise.all(specs.map(spec=>this.acquire(spec.url,record).then(data=>spec.aliases?spec.aliases.map(alias=>{const source=data.find(r=>r.id===alias.source);if(!source)throw Error('Missing shared railway '+alias.source);return {...source,id:alias.id,group:alias.group,sharedGeometry:alias.source}}):data)));if(this.records.get(key)!==record||!this.wanted.has(key))return;record.status='loaded';record.data=rows.flat();this.emit()}catch(error){if(this.records.get(key)!==record||!this.wanted.has(key))return;this.release(record);record.urls=[];record.status='error';record.error=error?.message?String(error.message).slice(0,180):'加载失败，请重试';this.emit()}finally{record.promise=null}})()}
 retry(key){if(!this.wanted.has(key))return;const old=this.records.get(key);if(old?.status==='loading')return;if(old)this.release(old);this.records.delete(key);this.load(key)}
 destroy(){this.wanted.clear();for(const r of this.records.values())this.release(r);this.records.clear();this.emit()}
};
